import { Game, WEAPONS, FIRE_LEVELS, TOWERS, PARTS, SPECIES } from './engine.js';
import { BIOMES, biomeAt } from './content.js';
import { PixelWorld } from './pixel-world.js';
import { Soundscape } from './audio.js';
const $=id=>document.getElementById(id),canvas=$('world');
const game=new Game(),world=new PixelWorld(canvas,game),sound=new Soundscape(),keys=new Set();
let auto=true,last=0,elapsed=0,accumulator=0,hudClock=0,phase='',toastUntil=0,bannerUntil=0,mouse={x:0,y:0,down:false,active:false},stick={x:0,y:0},stickId=null;
const clockText=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');toastUntil=elapsed+3.5;}
function banner(text){$('banner-text').textContent=text;$('wave-banner').classList.add('visible');bannerUntil=elapsed+2.4;}
function panel(id){$('overlay').hidden=!id;for(const name of ['start','pause','mutation','end','anatomy'])$(name+'-panel').hidden=id!==name;}
function selectWeapon(id){if(!game.setWeapon(id))return;updateHUD();}
function selectPart(id){game.selectPart(id);updateHUD();}
function cyclePart(delta){const i=game.body.indexOf(game.selectedPart);selectPart(game.body[(i+delta+game.body.length)%game.body.length].id);}
let workshopReturn='playing',partListSignature='';
function workshop(){if(game.phase==='anatomy'){game.phase=workshopReturn;}else if(['playing','paused'].includes(game.phase)){workshopReturn=game.phase;game.phase='anatomy';}else return;keys.clear();mouse.down=false;stick={x:0,y:0};syncPhase();updateHUD();}
function upgrade(){game.upgradePart();handleEvents();updateHUD();}
$('part-prev').onclick=()=>cyclePart(-1);$('part-next').onclick=()=>cyclePart(1);$('body-workshop').onclick=workshop;$('close-workshop').onclick=workshop;$('upgrade-part').onclick=upgrade;$('edit-upgrade').onclick=upgrade;
for(const w of WEAPONS){const o=document.createElement('option');o.value=w.id;o.textContent=w.name;$('organ-weapon').append(o);}$('organ-weapon').onchange=e=>selectWeapon(e.target.value);
function updateOrgans(){
 const n=game.selectedPart,w=game.organStats(n),index=game.body.indexOf(n)+1,cost=game.upgradeCost(n),can=['playing','paused','anatomy'].includes(game.phase)&&n.level<5&&game.canSpend(cost);
 const name=`${String(index).padStart(2,'0')} · ${PARTS[n.kind].name}`;
 $('part-name').textContent=name;$('part-stats').textContent=`LV ${n.level}/5 · ${w.name}`;
 for(const id of ['upgrade-part','edit-upgrade']){$(id).textContent=n.level>=5?'FULLY EVOLVED':`UPGRADE · ${cost}g${id==='upgrade-part'?' · U':''}`;$(id).disabled=!can;}
 $('edit-name').textContent=name;$('edit-lineage').textContent=`Level ${n.level}/5 · ${SPECIES[n.species]?.name||'Original tissue'} · ${n.parent===null?'Core':`Linked to part ${game.body.findIndex(p=>p.id===n.parent)+1}`}`;
 $('organ-weapon').value=n.weapon;$('edit-stats').textContent=`${(w.damage*game.stats.damage).toFixed(0)} base damage · ${Math.round(w.range*game.stats.range)}m range · ${(w.interval*game.stats.interval).toFixed(2)}s base interval. ${w.description}`;
 $('weapon-description').textContent=`PART ${index} / LV ${n.level} · ${w.description} Other organs keep firing their own weapons.`;
 for(const b of document.querySelectorAll('[data-weapon]')){const selected=b.dataset.weapon===n.weapon;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));b.querySelector('small').textContent=`${game.body.filter(p=>p.weapon===b.dataset.weapon).length} EQUIPPED`;}
 const signature=game.body.map(p=>`${p.id}:${p.weapon}:${p.level}`).join('|')+':'+n.id;
 if(signature!==partListSignature){partListSignature=signature;$('part-list').replaceChildren();for(const [i,p] of game.body.entries()){const b=document.createElement('button');b.dataset.part=p.id;b.className='part-row'+(p.id===n.id?' selected':'');b.setAttribute('aria-pressed',String(p.id===n.id));b.innerHTML=`<span>${String(i+1).padStart(2,'0')} ${p.parent!==null?'↳ ':''}${PARTS[p.kind].name}</span><small>LV ${p.level} · ${WEAPONS.find(w=>w.id===p.weapon).name}</small>`;b.onclick=()=>selectPart(p.id);$('part-list').append(b);}}
}
function selectFire(level){game.setFireLevel(level);for(const b of document.querySelectorAll('[data-fire]')){const active=Number(b.dataset.fire)===game.fireLevel;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));}updateHUD();}
function selectTower(id){game.setTower(id);for(const b of document.querySelectorAll('[data-tower]')){const active=b.dataset.tower===id;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));}$('tower-description').textContent=TOWERS.find(t=>t.id===id).description;updateHUD();}
for(const [i,w] of WEAPONS.entries()){const b=document.createElement('button');b.className='weapon';b.dataset.weapon=w.id;b.innerHTML=`<kbd>${i+1}</kbd><span class="weapon-glyph">${w.glyph}</span><span><b>${w.name}</b><small>${w.id==='tongue'||w.id==='scream'?'AREA ORGAN':'RANGED ORGAN'}</small></span>`;b.onclick=()=>selectWeapon(w.id);b.title=w.description;$('weapons').append(b);}
for(const f of FIRE_LEVELS){const b=document.createElement('button');b.className='fire-level';b.dataset.fire=f.id;b.textContent=f.name;b.title=f.label+' · every organ fires; changes output, mass cost and cadence';b.onclick=()=>selectFire(f.id);$('fire-levels').append(b);}
for(const t of TOWERS){const b=document.createElement('button');b.className='tower-option';b.dataset.tower=t.id;b.innerHTML=`<b>${t.name}</b><small>${t.cost}g</small>`;b.title=t.description;b.onclick=()=>selectTower(t.id);$('tower-options').append(b);}
function endRun(){panel('end');$('end-copy').textContent='The flesh ran dry. Feed more, reduce discharge, or reabsorb your surviving hunters.';$('end-stats').innerHTML=`<div><b>${game.kills}</b><span>KILLS</span></div><div><b>${Math.floor(game.peak)}g</b><span>PEAK MASS</span></div><div><b>${game.body.length}</b><span>ORGANS</span></div>`;let best=game.kills;try{best=Math.max(best,Number(localStorage.getItem('organism-best')||0));localStorage.setItem('organism-best',String(best));}catch{}$('best').textContent=`Best: ${best} kills · Survived ${clockText(game.time)}`;$('restart').focus();}
function syncPhase(){if(phase===game.phase)return;phase=game.phase;
 if(phase==='ready')panel('start');else if(phase==='playing'){panel(null);$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause game');canvas.focus({preventScroll:true});}
 else if(phase==='paused'){panel('pause');$('pause').textContent='▷';$('pause').setAttribute('aria-label','Resume game');$('resume').focus();}
 else if(phase==='anatomy'){panel('anatomy');$('close-workshop').focus();}
 else if(phase==='lost')endRun();
 else if(phase==='mutation'){panel('mutation');keys.clear();mouse.down=false;$('choices').replaceChildren();for(const m of game.choices){const b=document.createElement('button');b.className='choice';b.innerHTML=`<span class="glyph">${m.glyph}</span><b>${m.name}</b><p>${m.description}</p><small>${m.tag} ↗</small>`;b.onclick=()=>{game.mutate(m.id);syncPhase();updateHUD();};$('choices').append(b);}$('choices').firstElementChild.focus();}}
function handleEvents(){sound.listenerX=game.player.x;for(const e of game.events){world.event(e);sound.effect(e.type,e);if(e.type==='message')toast(e.text);else if(e.type==='wave')banner(`INFECTION ${String(e.wave).padStart(2,'0')}`);else if(e.type==='graft'&&e.species!=='origin')toast(`${PARTS[e.kind].name.toUpperCase()} GRAFTED · ${SPECIES[e.species]?.group||'Mutation'} tissue`);else if(e.type==='colonydeath')toast('A colony has been consumed. You can still spread.');}game.events=[];}
function radar(){const c=$('radar').getContext('2d'),p=game.player;c.clearRect(0,0,140,92);c.fillStyle='#10151dd9';c.fillRect(0,0,140,92);c.strokeStyle='#69756525';for(const r of [18,36]){c.beginPath();c.arc(70,46,r,0,Math.PI*2);c.stroke();}const plot=(e,color,size)=>{const x=70+(e.x-p.x)*.1,y=46+(e.y-p.y)*.1;if(x<2||y<2||x>138||y>90)return;c.fillStyle=color;c.fillRect(Math.round(x-size/2),Math.round(y-size/2),size,size);};for(const e of game.enemies)plot(e,'#bc647b',2);for(const a of game.allies)plot(a,'#729c9c',2);for(const colony of game.colonies)plot(colony,'#c8bf7e',4);plot(p,'#ead8c0',3);}
function updateHUD(){const p=game.player;$('mass').innerHTML=`${Math.max(0,Math.floor(p.mass))}<small>g</small>`;$('organs').textContent=String(game.body.length).padStart(2,'0');$('colony-count').textContent=String(game.colonies.length).padStart(2,'0');$('wave').innerHTML=`${String(game.wave).padStart(2,'0')}<small> / ∞</small>`;$('kills').textContent=game.kills;$('timer').textContent=clockText(game.time);$('coordinates').textContent=`${Math.round(p.x)} / ${Math.round(p.y)}`;$('biome').textContent=BIOMES[biomeAt(p.x,p.y)];
 const anatomy=new Map();for(const n of game.body)if(n.species!=='origin')anatomy.set(n.kind,(anatomy.get(n.kind)||0)+1);$('anatomy-list').innerHTML=anatomy.size?[...anatomy].slice(-7).map(([id,n])=>`<div class="anatomy-entry"><span>${PARTS[id].name}</span><b>×${n}</b></div>`).join(''):'<p>Eat a corpse. Keep its parts.</p>';$('species-count').textContent=Object.keys(game.absorbed).filter(s=>s!=='origin'&&s!=='mutation').length+' SPECIES';$('xpbar').style.width=Math.min(100,game.xp/game.xpGoal*100)+'%';$('xptext').textContent=`${Math.floor(game.xp)} / ${game.xpGoal}`;$('level').textContent=`MUTATION ${String(game.level-1).padStart(2,'0')}`;
 const counts=new Map();for(const id of game.mutations)counts.set(id,(counts.get(id)||0)+1);$('mutations').innerHTML=[...counts].map(([id,n])=>`<span class="mutation-tag">${id}${n>1?' ×'+n:''}</span>`).join('');
 const plan=game.firePlan();$('volley-info').textContent=`${plan.count} armed parts · ${plan.cost.toFixed(2)}g full volley`;const tower=TOWERS.find(t=>t.id===game.towerType);$('tower-cost').textContent=`${Math.ceil(game.buildCost('tower'))}g · ${tower.name.toLowerCase()}`;$('colony-cost').textContent=`${Math.ceil(game.buildCost('colony'))}g · spread the infection`;
 for(const b of document.querySelectorAll('[data-tower]'))b.querySelector('small').textContent=Math.ceil(TOWERS.find(t=>t.id===b.dataset.tower).cost*game.stats.buildCost)+'g';
 for(const kind of ['shield','drone','tower','colony'])$(kind).disabled=game.phase!=='playing'||!game.canSpend(game.buildCost(kind));$('recall').disabled=game.phase!=='playing'||!game.allies.some(a=>a.kind!=='tower');
 $('statusline').textContent=p.mass<25?'LOW BIOMASS // SIP. FEED. REABSORB.':`${game.body.length} ORGANS / ${game.allies.filter(a=>a.kind==='drone').length} HUNTERS / ${game.explored.size} SECTORS EXPLORED`;radar();updateOrgans();}
function start(){sound.unlock().catch(()=>toast('Use the sound button to retry audio.'));keys.clear();game.start();syncPhase();toast('Eat the marked remains nearby. B opens your body workshop. All organs fire together.');}
function restart(){game.reset();world.reset();mouse.down=false;keys.clear();stick={x:0,y:0};phase='';selectWeapon('acid');selectFire(1);selectTower('spitter');start();}
function pause(){if(game.phase==='anatomy'){workshop();return;}game.pause();keys.clear();mouse.down=false;stick={x:0,y:0};syncPhase();}
$('start').onclick=start;$('restart').onclick=restart;$('restart-pause').onclick=restart;$('pause').onclick=pause;$('resume').onclick=pause;
$('sound').onclick=()=>{$('audio-panel').hidden=!$('audio-panel').hidden;$('sound').setAttribute('aria-expanded',String(!$('audio-panel').hidden));sound.unlock().catch(()=>toast('Audio unavailable.'));};
$('music-volume').oninput=e=>{sound.setVolume('music',Number(e.target.value)/100);$('music-value').textContent=e.target.value+'%';};$('effects-volume').oninput=e=>{sound.setVolume('effects',Number(e.target.value)/100);$('effects-value').textContent=e.target.value+'%';};$('mute-all').onclick=()=>{sound.setMuted(!sound.muted);$('mute-all').textContent=sound.muted?'Enable all audio':'Mute all audio';$('sound').classList.toggle('muted',sound.muted);};
function toggleAuto(){auto=!auto;$('autofire').classList.toggle('active',auto);$('autofire').setAttribute('aria-pressed',String(auto));$('autofire').querySelector('b').textContent='AUTO FIRE: '+(auto?'ON':'OFF');}$('autofire').onclick=toggleAuto;
for(const b of document.querySelectorAll('[data-action]'))b.onclick=()=>{game.action(b.dataset.action);handleEvents();updateHUD();canvas.focus({preventScroll:true});};
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;const key=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(e.repeat)return;keys.add(key);if(key==='escape'){pause();return;}if(key==='b'){workshop();return;}if(game.phase==='playing'){if(key==='u')upgrade();if(key==='[')cyclePart(-1);if(key===']')cyclePart(1);if(/^[1-7]$/.test(key))selectWeapon(WEAPONS[Number(key)-1].id);if(key==='z'){selectFire((game.fireLevel+1)%3);canvas.focus({preventScroll:true});}if(key==='t'){const i=TOWERS.findIndex(t=>t.id===game.towerType);selectTower(TOWERS[(i+1)%TOWERS.length].id);}if(key==='f')toggleAuto();const action={q:'shield',e:'drone',r:'tower',c:'colony',x:'recall'}[key];if(action){game.action(action);handleEvents();}}else if(game.phase==='ready'&&key==='enter'){e.preventDefault();start();}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('resize',()=>world.resize());window.addEventListener('blur',()=>{if(game.phase==='playing')pause();keys.clear();mouse.down=false;});document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.phase==='playing')pause();});
canvas.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;mouse.active=true;});canvas.addEventListener('pointerdown',e=>{if(game.phase!=='playing')return;mouse={x:e.clientX,y:e.clientY,down:true,active:true};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointerup',()=>mouse.down=false);canvas.addEventListener('pointercancel',()=>mouse.down=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());
const joy=$('joystick');function moveStick(e){const r=joy.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,d=Math.max(28,Math.hypot(dx,dy));stick={x:dx/d,y:dy/d};joy.querySelector('i').style.transform=`translate(${stick.x*22}px,${stick.y*22}px)`;}joy.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;joy.setPointerCapture(e.pointerId);moveStick(e);});joy.addEventListener('pointermove',e=>{if(e.pointerId===stickId)moveStick(e);});function releaseStick(){stickId=null;stick={x:0,y:0};joy.querySelector('i').style.transform='';}joy.addEventListener('pointerup',releaseStick);joy.addEventListener('pointercancel',releaseStick);
function frame(now){const dt=Math.min(.05,(now-last)/1000||.016);last=now;elapsed+=dt;accumulator+=dt;while(accumulator>=1/60){if(game.phase==='playing'){game.tick(1/60,{x:(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+stick.x,y:(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+stick.y,fire:mouse.down||keys.has(' '),aim:mouse.active?world.screenToWorld(mouse.x,mouse.y):{x:game.player.x+Math.cos(game.player.angle)*200,y:game.player.y+Math.sin(game.player.angle)*200},auto});handleEvents();}accumulator-=1/60;}syncPhase();sound.update(game);world.render(dt);if(elapsed>toastUntil)$('toast').classList.remove('visible');if(elapsed>bannerUntil)$('wave-banner').classList.remove('visible');hudClock+=dt;if(hudClock>.15){updateHUD();hudClock=0;}requestAnimationFrame(frame);}
selectWeapon('acid');selectFire(1);selectTower('spitter');syncPhase();requestAnimationFrame(frame);
window.organism={snapshot:()=>({phase:game.phase,mass:game.player.mass,position:{x:game.player.x,y:game.player.y},selectedPartId:game.selectedPartId,body:game.body.map(n=>({id:n.id,weapon:n.weapon,level:n.level,cooldown:n.cooldown,kind:n.kind,species:n.species,parent:n.parent,x:n.x,y:n.y})),colonies:game.colonies.map(c=>({x:c.x,y:c.y,hp:c.hp})),allies:game.allies.map(a=>({kind:a.kind,tower:a.tower,x:a.x,y:a.y,target:a.target})),enemies:game.enemies.length,kills:game.kills,food:game.food.length,wave:game.wave,level:game.level,time:game.time,weapon:game.weapon,fireLevel:game.fireLevel,volley:game.firePlan().cost,explored:game.explored.size,audio:sound.snapshot()})};
